bool SubscriptionLifecycleEvents::validJsonOfField(size_t index,
                                                   const std::string &fieldName,
                                                   const Json::Value &pJson,
                                                   std::string &err,
                                                   bool isForCreation)
{
    switch(index)
    {

        case 0:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 1:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 2:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 3:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 4:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 5:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 6:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            if(pJson.isString() && drogon::utils::utf8Length(pJson.asCString()) > 40)
            {
                err="String length exceeds limit for the " +
                    fieldName +
                    " field (the maximum value is 40)";
                return false;
            }

            break;

        case 7:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 8:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 9:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            if(pJson.isString() && drogon::utils::utf8Length(pJson.asCString()) > 100)
            {
                err="String length exceeds limit for the " +
                    fieldName +
                    " field (the maximum value is 100)";
                return false;
            }

            break;

        case 10:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 11:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        default:
            err="Internal error in the server";
            return false;
    }
    return true;
}

CommercialPartners SubscriptionLifecycleEvents::getCommercialPartners(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from commercial_partners where id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *partnerId_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    if (r.size() == 0)
    {
        throw UnexpectedRows("0 rows found");
    }
    else if (r.size() > 1)
    {
        throw UnexpectedRows("Found more than one row");
    }
    return CommercialPartners(r[0]);
}

